-- Sujet de français, examen régional 2014 (session de rattrapage), académie
-- Laâyoune-Sakia El Hamra, sur Antigone.
-- Transcrit mot pour mot depuis le PDF de l'académie publié sur
-- moutamadris.ma (« الامتحان الجهوي في اللغة الفرنسية 2014 جهة العيون الساقية الحمراء »).
-- Corrigé et barème officiels recopiés question par question.
--
-- L'en-tête (en arabe) nomme « الأكاديمية الجهوية للتربية و التكوين لجهة العيون
-- بوجدور الساقية الحمراء » (Laâyoune-Boujdour-Sakia El Hamra, avant le découpage
-- régional de 2015) ; « الدورة الاستدراكية 2014 » (session de rattrapage),
-- « السنة الأولى رسميون », durée « 2 س », coefficient « 4 - 3 » selon la série
-- (non saisi), filière « الشعب الأدبية و العلمية و التقنية و الاقتصادية », code 105.
-- Question 2 : la feuille porte « 1pt » pour l'ensemble (a et b) ; le corrigé
-- donne 0,5 pt à chaque partie.
--
-- À lancer après 20261003000000_annales.sql. Rejouable : le sujet est
-- remplacé s'il existe déjà.

insert into public.annales
  (matiere, annee, session, academie, oeuvre, filiere_libelle, duree_minutes, enonce_mdx, corrige_mdx, questions)
values (
  $sujet$francais$sujet$,
